import type { BankQuestion } from "@/lib/bank";

/** Thermodynamics and Kinetic Theory (Physics (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-thermodynamics-kinetic-theory-1","question":"The first law of thermodynamics, with ΔQ the heat supplied, ΔU the change in internal energy and ΔW the work done by the system, is:","options":["ΔQ = ΔU − ΔW","ΔQ = ΔU + ΔW","ΔU = ΔQ + ΔW","ΔW = ΔQ + ΔU"],"answer":1,"explanation":"Heat supplied goes partly into internal energy and partly into work done by the gas: ΔQ = ΔU + ΔW (sign convention: W positive when done by the system).","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-2","question":"For an ideal gas the molar specific heats at constant pressure and constant volume are related by:","options":["Cp − Cv = R","Cp + Cv = R","Cp/Cv = R","Cv − Cp = R"],"answer":0,"explanation":"Mayer's relation Cp − Cv = R: at constant pressure extra heat R per mole per kelvin is needed for the expansion work. Cp/Cv is γ, not R.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-3","question":"The average kinetic energy of a molecule of an ideal gas is directly proportional to its:","options":["pressure","volume","square root of absolute temperature","absolute temperature"],"answer":3,"explanation":"Average translational KE per molecule = (3/2)kT, proportional to the absolute temperature; it is the rms speed, not the energy, that goes as √T.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-4","question":"An ideal gas absorbs 500 J of heat while expanding isothermally. The work done by the gas is:","options":["500 J","250 J","0","1000 J"],"answer":0,"explanation":"For an ideal gas U depends only on T, so ΔU = 0 in an isothermal process and ΔW = ΔQ = 500 J.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-5","question":"A Carnot engine operates between a source at 500 K and a sink at 300 K. Its efficiency is:","options":["60%","20%","80%","40%"],"answer":3,"explanation":"η = 1 − T₂/T₁ = 1 − 300/500 = 0.4 = 40%. Using Celsius temperatures would give a wrong answer; absolute temperatures must be used.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-6","question":"At the same temperature, the ratio of the rms speed of hydrogen molecules to that of oxygen molecules is:","options":["2","16","1/4","4"],"answer":3,"explanation":"v_rms = √(3RT/M), so v(H₂)/v(O₂) = √(M_O₂/M_H₂) = √(32/2) = 4.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-7","question":"The ratio Cp/Cv for a diatomic gas at ordinary temperature (molecules treated as rigid) is:","options":["5/3","7/5","4/3","3/2"],"answer":1,"explanation":"With 5 degrees of freedom (3 translational + 2 rotational), Cv = 5R/2, Cp = 7R/2 and γ = 7/5 = 1.4. 5/3 is for a monoatomic gas, 4/3 for a non-linear triatomic gas.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-8","question":"A 1 m long metal rod with coefficient of linear expansion 12 × 10⁻⁶ per °C is heated through 50 °C. Its increase in length is:","options":["6 mm","0.06 mm","0.6 mm","1.2 mm"],"answer":2,"explanation":"ΔL = αLΔT = 12 × 10⁻⁶ × 1 × 50 = 6 × 10⁻⁴ m = 0.6 mm.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-9","question":"The heat required to melt 100 g of ice at 0 °C into water at 0 °C (latent heat of fusion = 80 cal/g) is:","options":["8 kcal","800 cal","80 kcal","0.8 kcal"],"answer":0,"explanation":"Q = mL = 100 × 80 = 8000 cal = 8 kcal; no temperature change is involved, only the phase change.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-10","question":"A monoatomic ideal gas at temperature T is compressed adiabatically to one-eighth of its volume. Its final temperature is:","options":["2T","8T","16T","4T"],"answer":3,"explanation":"TV^(γ−1) = constant with γ − 1 = 2/3: T₂ = T × 8^(2/3) = 4T.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-11","question":"A gas is taken clockwise around a rectangular cycle on a P–V diagram between pressures 1 × 10⁵ Pa and 3 × 10⁵ Pa and volumes 1 L and 3 L. The net work done by the gas per cycle is:","options":["200 J","−400 J","800 J","400 J"],"answer":3,"explanation":"Net work = enclosed area = ΔP × ΔV = (2 × 10⁵ Pa)(2 × 10⁻³ m³) = 400 J, positive because the cycle is clockwise (work done by the gas).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-12","question":"Two moles of a diatomic ideal gas are heated at constant pressure through 50 K. The heat supplied is:","options":["350 R","500 R","250 R","100 R"],"answer":0,"explanation":"Q = nCpΔT = 2 × (7R/2) × 50 = 350R. Of this, ΔU = nCvΔT = 250R and the work done is nRΔT = 100R.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-13","question":"One mole of helium is mixed with one mole of oxygen (both ideal, oxygen rigid diatomic). The ratio Cp/Cv of the mixture is:","options":["1.4","1.5","1.67","1.33"],"answer":1,"explanation":"Cv(mix) = (3R/2 + 5R/2)/2 = 2R, Cp(mix) = Cv + R = 3R, so γ = 3R/2R = 1.5. Averaging the individual γ values (1.67 and 1.4) is not valid.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-14","question":"A Carnot refrigerator works between 240 K (inside) and 300 K (room). Its coefficient of performance is:","options":["5","0.2","3","4"],"answer":3,"explanation":"COP = T₂/(T₁ − T₂) = 240/(300 − 240) = 4: four joules of heat are removed from the cold space for every joule of work.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-15","question":"If the pressure of an ideal gas is doubled at constant temperature, the mean free path of its molecules:","options":["doubles","is unchanged","becomes four times","halves"],"answer":3,"explanation":"λ = kT/(√2 π d² P): at constant T doubling P doubles the number density and halves the mean free path.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-16","question":"10 g of ice at 0 °C is added to 100 g of water at 30 °C in an insulated vessel (latent heat of ice = 80 cal/g, specific heat of water = 1 cal/g °C). The final temperature is:","options":["20 °C","27 °C","25 °C","22 °C"],"answer":0,"explanation":"Heat lost by water = heat to melt ice + heat to warm the melt: 100(30 − T) = 10 × 80 + 10(T − 0), so 3000 − 100T = 800 + 10T and T = 2200/110 = 20 °C.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-17","question":"A pendulum clock keeps correct time at 20 °C. Its pendulum has coefficient of linear expansion 2 × 10⁻⁵ per °C. At 40 °C the clock loses per day about:","options":["8.64 s","34.56 s","17.28 s","1.728 s"],"answer":2,"explanation":"T ∝ √L, so ΔT/T = ½αΔθ = ½ × 2 × 10⁻⁵ × 20 = 2 × 10⁻⁴. Loss per day = 2 × 10⁻⁴ × 86400 = 17.28 s. Forgetting the ½ gives 34.56 s.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-18","question":"The density of a gas is 1.2 kg/m³ at a pressure of 1 × 10⁵ Pa. The rms speed of its molecules is:","options":["250 m/s","1000 m/s","707 m/s","500 m/s"],"answer":3,"explanation":"P = (1/3)ρ v_rms², so v_rms = √(3P/ρ) = √(3 × 10⁵/1.2) = √(2.5 × 10⁵) = 500 m/s.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-19","question":"One mole of a monoatomic ideal gas at pressure P and volume V expands at constant pressure to 2V. The heat absorbed in this step is:","options":["5PV/2","PV","3PV/2","2PV"],"answer":0,"explanation":"At constant pressure nRΔT = PΔV = PV, so Q = nCpΔT = (5/2)PV; of this, ΔU = (3/2)PV and the work done is PV.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-20","question":"How many of the following statements are correct?\n(A) The efficiency of a Carnot engine depends only on the temperatures of the source and the sink.\n(B) A Carnot cycle consists of two isothermal and two isochoric processes.\n(C) The entropy of an isolated system never decreases.\n(D) Heat can flow spontaneously from a colder to a hotter body without any external work.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(A) and (C) are correct. (B) is false — the Carnot cycle has two isothermal and two adiabatic processes. (D) contradicts the Clausius statement of the second law.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-21","question":"Two moles of a monoatomic ideal gas expand adiabatically and the temperature falls from 400 K to 300 K. The work done by the gas is:","options":["200 R","300 R","500 R","150 R"],"answer":1,"explanation":"In an adiabatic process Q = 0, so W = −ΔU = nCv(T₁ − T₂) = 2 × (3R/2) × 100 = 300R (≈ 2494 J).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-22","question":"One mole of an ideal gas at 300 K expands isothermally and reversibly from volume V to 4V. The heat absorbed by the gas is:","options":["300 R ln 2","600 R ln 2","1200 R ln 2","0"],"answer":1,"explanation":"ΔU = 0, so Q = W = nRT ln(V₂/V₁) = 300R ln 4 = 600R ln 2 (≈ 3.46 kJ). The gas absorbs heat even though its temperature does not change.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-23","question":"A Carnot engine has an efficiency of 1/6. When the sink temperature is lowered by 62 K, the efficiency becomes 1/3. The temperature of the source is:","options":["310 K","400 K","300 K","372 K"],"answer":3,"explanation":"1 − T₂/T₁ = 1/6 gives T₂ = 5T₁/6; 1 − (T₂ − 62)/T₁ = 1/3 gives T₂ − 62 = 2T₁/3. Subtracting: 62 = 5T₁/6 − 2T₁/3 = T₁/6, so T₁ = 372 K (and T₂ = 310 K).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-24","question":"At what temperature will the rms speed of oxygen molecules equal the rms speed of hydrogen molecules at 20 K?","options":["160 K","320 K","80 K","640 K"],"answer":1,"explanation":"v_rms ∝ √(T/M); equal speeds need T(O₂)/32 = 20/2, so T(O₂) = 320 K.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-25","question":"A monoatomic ideal gas undergoes a process in which PV² = constant. Its molar heat capacity for this process is:","options":["3R/2","5R/2","R/2","−R/2"],"answer":2,"explanation":"For PVⁿ = constant, C = Cv + R/(1 − n). With n = 2 and Cv = 3R/2: C = 3R/2 − R = R/2. (The gas cools as it expands, so C is less than Cv.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-26","question":"Assertion (A): In the free expansion of an ideal gas into a vacuum (insulated container) the temperature remains unchanged.\nReason (R): No work is done and no heat is exchanged, so the internal energy, which for an ideal gas depends only on temperature, is unchanged.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Expansion against zero pressure does no work and the walls are insulated, so ΔU = 0; for an ideal gas this means ΔT = 0. R is precisely the explanation of A. (A real gas would cool slightly.)","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-27","question":"A solid has coefficient of linear expansion α. When it is heated through Δθ, its density decreases by the fraction (for small αΔθ):","options":["3αΔθ","2αΔθ","αΔθ","αΔθ/3"],"answer":0,"explanation":"Volume increases by the fraction γΔθ = 3αΔθ while the mass is unchanged, so the density falls by approximately 3αΔθ. (2αΔθ is the fractional change in area.)","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-28","question":"An engine is claimed to absorb 1000 J of heat from a source at 500 K and reject 500 J to a sink at 300 K per cycle. Which statement is correct?","options":["It is a possible reversible engine","It is a possible irreversible engine","It violates the second law of thermodynamics","Its efficiency is 40%"],"answer":2,"explanation":"The claimed efficiency is 500/1000 = 50%, but the Carnot limit between 500 K and 300 K is 1 − 300/500 = 40%. No engine can exceed the Carnot efficiency, so the claim violates the second law.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-29","question":"An ideal gas undergoes a process in which the pressure is directly proportional to the volume (P ∝ V). Starting at pressure P₁ and volume V₁, the volume is doubled. The work done by the gas is:","options":["P₁V₁","3P₁V₁/2","2P₁V₁","P₁V₁/2"],"answer":1,"explanation":"P = kV with k = P₁/V₁; W = ∫kV dV from V₁ to 2V₁ = k(4V₁² − V₁²)/2 = 3P₁V₁/2 (the trapezoidal area under the straight line). The temperature rises to 4T₁ in this process.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-30","question":"Match each process of an ideal gas with the quantity that is zero or given:\n(a) Isothermal\n(b) Adiabatic\n(c) Isochoric\n(d) Isobaric\n1. ΔU = 0  2. Q = 0  3. W = 0  4. Q = nCpΔT","options":["a-2, b-1, c-3, d-4","a-1, b-3, c-2, d-4","a-3, b-2, c-1, d-4","a-1, b-2, c-3, d-4"],"answer":3,"explanation":"Isothermal: T constant so ΔU = 0; adiabatic: no heat exchange, Q = 0; isochoric: no volume change, W = 0; isobaric: heat supplied is nCpΔT.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-31","question":"The zeroth law of thermodynamics leads to the concept of:","options":["entropy","internal energy","temperature","heat"],"answer":2,"explanation":"If A and B are each in thermal equilibrium with C, they are in equilibrium with each other; the common property they share is temperature. Internal energy comes from the first law and entropy from the second.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-32","question":"For a rigid diatomic ideal gas molecule at absolute temperature T, the average total kinetic energy per molecule is:","options":["3kT/2","7kT/2","kT","5kT/2"],"answer":3,"explanation":"A rigid diatomic molecule has 3 translational and 2 rotational degrees of freedom, each with ½kT, giving 5kT/2. 3kT/2 is the translational part only.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-33","question":"One mole of an ideal gas is heated at constant pressure through 10 K (R = 8.31 J/mol K). The work done by the gas is:","options":["207.75 J","290.85 J","124.65 J","83.1 J"],"answer":3,"explanation":"At constant pressure W = PΔV = nRΔT = 1 × 8.31 × 10 = 83.1 J, whatever the atomicity of the gas.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-34","question":"A heat engine absorbs 1000 J from a source and rejects 600 J to a sink in each cycle. Its efficiency is:","options":["60%","40%","25%","1.67%"],"answer":1,"explanation":"η = W/Q₁ = (1000 − 600)/1000 = 0.4 = 40%. 60% is the fraction rejected.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-35","question":"The temperature of a black body is raised so that the wavelength at which it emits most strongly is halved. The total power it radiates becomes:","options":["4 times","2 times","16 times","8 times"],"answer":2,"explanation":"Wien's law: λ_max T = constant, so T doubles. Stefan's law: P ∝ T⁴ = 2⁴ = 16 times.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-36","question":"A body cools from 60 °C to 50 °C in 10 minutes in surroundings at 20 °C. Assuming Newton's law of cooling, its temperature after the next 10 minutes is:","options":["40 °C","41.7 °C","42.5 °C","45 °C"],"answer":2,"explanation":"The excess over the surroundings falls by the same factor in equal times: 40 → 30 is a factor 3/4, so 30 → 22.5, i.e. 42.5 °C. Assuming the same 10 °C drop (40 °C) ignores the slower cooling at lower excess.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-37","question":"Two rods of equal length and cross-section, with thermal conductivities K and 2K, are joined end to end. The free end of the first is kept at 100 °C and that of the second at 0 °C. The temperature of the junction in the steady state is:","options":["50 °C","66.7 °C","33.3 °C","25 °C"],"answer":2,"explanation":"Equal heat current: K(100 − T) = 2K(T − 0) → T = 100/3 ≈ 33.3 °C. The better conductor has the smaller temperature drop.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-thermodynamics-kinetic-theory-38","question":"The rms speed of the molecules of a gas at 27 °C is v. The temperature at which their rms speed becomes 2v is:","options":["627 °C","927 °C","108 °C","1200 °C"],"answer":1,"explanation":"v_rms ∝ √T, so T must become 4 × 300 K = 1200 K = 927 °C. 1200 °C forgets to convert back from kelvin.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-39","question":"One mole of a monatomic ideal gas is taken around the cycle A(P₀, V₀) → B(2P₀, V₀) → C(2P₀, 2V₀) → D(P₀, 2V₀) → A, in which each step is isochoric or isobaric. The efficiency of the cycle is:","options":["1/9","2/13","2/11","1/4"],"answer":1,"explanation":"Net work = area = P₀V₀. Heat absorbed: A→B (isochoric) = (3/2)(2P₀V₀ − P₀V₀) = 1.5P₀V₀; B→C (isobaric) = (5/2)(4P₀V₀ − 2P₀V₀) = 5P₀V₀. Total 6.5P₀V₀, so η = 1/6.5 = 2/13 ≈ 15%.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-40","question":"Two thermally insulated vessels contain the same ideal gas at (P₁, V₁, T₁) and (P₂, V₂, T₂). They are connected by a narrow tube of negligible volume. The final common temperature is:","options":["(T₁ + T₂)/2","(V₁T₁ + V₂T₂)/(V₁ + V₂)","(P₁V₁ + P₂V₂)/(P₁V₁/T₁ + P₂V₂/T₂)","(P₁V₁T₁ + P₂V₂T₂)/(P₁V₁ + P₂V₂)"],"answer":2,"explanation":"No heat or work is exchanged with the outside, so the total internal energy n₁CᵥT₁ + n₂CᵥT₂ = (n₁ + n₂)CᵥT is conserved, with nᵢ = PᵢVᵢ/RTᵢ. Hence T = (P₁V₁ + P₂V₂)/(P₁V₁/T₁ + P₂V₂/T₂).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-41","question":"How many of the following statements about an ideal gas are correct?\n(A) Its pressure is P = (1/3)ρv²_rms.\n(B) Its internal energy depends only on its temperature.\n(C) At the same temperature, molecules of all ideal gases have the same average translational kinetic energy.\n(D) The mean free path of its molecules increases as the number density increases.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and C are correct. D is wrong: mean free path = 1/(√2 πd²n), which decreases as the number density n increases. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-42","question":"A liquid has a coefficient of real (volume) expansion of 5 × 10⁻⁴ per °C. It is heated in a glass vessel whose coefficient of linear expansion is 1 × 10⁻⁵ per °C. Its coefficient of apparent expansion is:","options":["5.1 × 10⁻⁴ per °C","5.3 × 10⁻⁴ per °C","4.7 × 10⁻⁴ per °C","4.9 × 10⁻⁴ per °C"],"answer":2,"explanation":"γ_apparent = γ_real − γ_vessel, and γ_vessel = 3α = 3 × 10⁻⁵ per °C. So γ_apparent = 5 × 10⁻⁴ − 0.3 × 10⁻⁴ = 4.7 × 10⁻⁴ per °C. Using α instead of 3α gives 4.9 × 10⁻⁴.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-43","question":"One mole of a monatomic ideal gas undergoes a process in which its volume is proportional to the square of its absolute temperature (V ∝ T²). The molar heat capacity of the gas in this process is:","options":["7R/2","3R/2","5R/2","2R"],"answer":0,"explanation":"With PV = RT and V ∝ T², P ∝ T/V ∝ 1/T ∝ V^(−1/2), so PV^(1/2) = constant (polytropic n = 1/2). C = Cᵥ + R/(1 − n) = 3R/2 + 2R = 7R/2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-44","question":"10 g of steam at 100 °C is passed into a large amount of ice at 0 °C, and the final temperature is 0 °C. Taking the latent heat of vaporisation as 540 cal/g, the latent heat of fusion as 80 cal/g and the specific heat of water as 1 cal/g °C, the mass of ice that melts is:","options":["67.5 g","80 g","13.5 g","100 g"],"answer":1,"explanation":"Heat given by the steam = 10 × 540 (condensing) + 10 × 1 × 100 (cooling to 0 °C) = 6400 cal. Ice melted = 6400/80 = 80 g. Forgetting the cooling of the condensed water gives 67.5 g.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-45","question":"Match the reversible process of n moles of an ideal gas (List I) with the work done by the gas (List II). List I: (P) isothermal; (Q) adiabatic; (R) isobaric; (S) isochoric. List II: (1) zero; (2) P(V₂ − V₁); (3) nRT ln(V₂/V₁); (4) (P₁V₁ − P₂V₂)/(γ − 1).","options":["P-3, Q-4, R-2, S-1","P-3, Q-4, R-1, S-2","P-4, Q-3, R-2, S-1","P-3, Q-2, R-4, S-1"],"answer":0,"explanation":"Isothermal: ∫P dV = nRT ln(V₂/V₁). Adiabatic: W = −ΔU = (P₁V₁ − P₂V₂)/(γ − 1). Isobaric: P(V₂ − V₁). Isochoric: no volume change, so no work.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-46", "question": "The internal energy of a fixed amount of an ideal gas depends only on its:", "options": ["pressure", "volume", "temperature", "pressure and volume separately"], "answer": 2, "explanation": "An ideal gas has no intermolecular forces, so its internal energy is purely kinetic and depends only on T (U = nC_vT). That is why ΔU = 0 in any isothermal process.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-47", "question": "The number of translational degrees of freedom of a molecule of a monatomic gas is:", "options": ["3", "5", "6", "7"], "answer": 0, "explanation": "A monatomic molecule can only move along x, y and z: 3 degrees of freedom, giving C_v = 3R/2. 5 is the value for a rigid diatomic molecule.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-48", "question": "The Sun's spectrum is most intense at a wavelength of about 500 nm. Taking Wien's constant as 2.9 × 10⁻³ m K, the Sun's surface temperature is about:", "options": ["1450 K", "58000 K", "2900 K", "5800 K"], "answer": 3, "explanation": "λ_max T = b gives T = 2.9 × 10⁻³/(500 × 10⁻⁹) = 5800 K.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-49", "question": "A metal plate has a circular hole in it. When the plate is heated uniformly, the diameter of the hole:", "options": ["decreases", "increases, as if the hole were made of the same metal", "remains unchanged", "increases or decreases depending on the plate's thickness"], "answer": 1, "explanation": "Thermal expansion enlarges every length in the plate by the same factor, so the hole grows exactly as a disc of the same metal would. It does not shrink.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-50", "question": "An ideal gas is at a pressure of 1 × 10⁵ Pa. The total translational kinetic energy of its molecules per unit volume is:", "options": ["1 × 10⁵ J/m³", "1.5 × 10⁵ J/m³", "0.67 × 10⁵ J/m³", "3 × 10⁵ J/m³"], "answer": 1, "explanation": "P = (2/3)(E/V), so E/V = (3/2)P = 1.5 × 10⁵ J/m³.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-51", "question": "200 g of water at 80 °C is mixed with 300 g of water at 20 °C in an insulated vessel of negligible heat capacity. The final temperature is:", "options": ["50 °C", "56 °C", "40 °C", "44 °C"], "answer": 3, "explanation": "Heat lost = heat gained: 200(80 − T) = 300(T − 20), so 16000 + 6000 = 500T and T = 44 °C. 50 °C is the plain average, valid only for equal masses.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-52", "question": "A Carnot engine absorbs 600 J of heat per cycle from a source at 600 K and rejects heat to a sink at 300 K. The work it does per cycle is:", "options": ["300 J", "600 J", "200 J", "400 J"], "answer": 0, "explanation": "η = 1 − 300/600 = 0.5, so W = ηQ₁ = 300 J, and the other 300 J goes to the sink.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-thermodynamics-kinetic-theory-53", "question": "Two rods of the same length are placed side by side (in parallel) between the same two heat reservoirs. One has conductivity K and cross-section A; the other has conductivity 3K and cross-section 2A. The equivalent conductivity of the combination, for a total cross-section of 3A, is:", "options": ["2K", "4K/3", "7K/3", "5K/2"], "answer": 2, "explanation": "In parallel the heat currents add: K_eq(3A) = KA + 3K(2A) = 7KA, so K_eq = 7K/3. 2K is the simple average, which ignores the different areas.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-54", "question": "For the molecules of an ideal gas at a given temperature, the rms speed, the average speed and the most probable speed are related as:", "options": ["v_mp > v_avg > v_rms", "v_avg > v_rms > v_mp", "v_rms = v_avg = v_mp", "v_rms > v_avg > v_mp"], "answer": 3, "explanation": "v_rms = √(3RT/M), v_avg = √(8RT/πM) and v_mp = √(2RT/M); since 3 > 8/π ≈ 2.55 > 2, the ratio is about 1.73 : 1.60 : 1.41.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-thermodynamics-kinetic-theory-55", "question": "The adiabatic bulk modulus of air (γ = 1.4) at a pressure of 1 × 10⁵ Pa is:", "options": ["1 × 10⁵ Pa", "1.4 × 10⁵ Pa", "0.71 × 10⁵ Pa", "2.4 × 10⁵ Pa"], "answer": 1, "explanation": "For PV^γ = constant, B = −V dP/dV = γP = 1.4 × 10⁵ Pa. The isothermal bulk modulus is P = 1 × 10⁵ Pa, the error Newton made for the speed of sound.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-56", "question": "Two black-body spheres have radii in the ratio 1 : 2 and absolute temperatures in the ratio 2 : 1. The ratio of the total power they radiate is:", "options": ["1 : 1", "16 : 1", "4 : 1", "2 : 1"], "answer": 2, "explanation": "P = σ(4πr²)T⁴, so P₁/P₂ = (1/2)² × 2⁴ = (1/4) × 16 = 4 : 1.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-thermodynamics-kinetic-theory-57", "question": "A refrigerator with a coefficient of performance of 4 removes heat from its interior at 400 J/s. The power it consumes and the rate at which it delivers heat to the room are:", "options": ["100 W and 500 W", "100 W and 300 W", "1600 W and 2000 W", "400 W and 800 W"], "answer": 0, "explanation": "COP = Q₂/W, so W = 400/4 = 100 W. The room receives Q₁ = Q₂ + W = 500 W. 300 W subtracts the work instead of adding it.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-58", "question": "A steel rod is clamped rigidly between two walls at 20 °C and then heated to 70 °C. With Young's modulus 2 × 10¹¹ Pa and α = 1.2 × 10⁻⁵ per °C, the thermal stress in the rod is:", "options": ["1.2 × 10⁶ Pa", "2.4 × 10⁸ Pa", "1.2 × 10⁸ Pa", "6 × 10⁷ Pa"], "answer": 2, "explanation": "The prevented strain is αΔT = 1.2 × 10⁻⁵ × 50 = 6 × 10⁻⁴, so stress = Y × strain = 2 × 10¹¹ × 6 × 10⁻⁴ = 1.2 × 10⁸ Pa (compressive).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-59", "question": "A cylinder holds gas at 10 atm and 27 °C. After some gas leaks out, the pressure is 8.7 atm and the temperature is 17 °C. The fraction of the gas that escaped is:", "options": ["10%", "13%", "3%", "87%"], "answer": 0, "explanation": "At fixed volume n ∝ P/T: n_f/n_i = (8.7/290)/(10/300) = 0.030/0.0333 = 0.9, so 10% escaped. 13% ignores the drop in temperature.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-60", "question": "How many of the following statements about an ideal gas are correct?\n(A) In an adiabatic compression the temperature of the gas rises.\n(B) Compressing a gas from V to V/2 needs more work adiabatically than isothermally.\n(C) At a given point of a P–V diagram, the adiabatic curve is γ times steeper than the isothermal curve.\n(D) No heat is exchanged in an isothermal process.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct (the adiabatic slope is −γP/V against −P/V for the isothermal, and the pressure rises faster, so more work is needed). D is wrong: in an isothermal expansion the gas absorbs heat equal to the work it does. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-61", "question": "50 g of ice at −20 °C is added to 100 g of water at 29 °C in an insulated vessel of negligible heat capacity (specific heat of ice 0.5 cal/g °C, of water 1 cal/g °C, latent heat of fusion 80 cal/g). In the final state the vessel contains:", "options": ["150 g of water at 4 °C", "50 g of ice and 100 g of water at 0 °C", "30 g of ice and 120 g of water at 0 °C", "20 g of ice and 130 g of water at 0 °C"], "answer": 3, "explanation": "Warming the ice to 0 °C needs 50 × 0.5 × 20 = 500 cal; cooling the water to 0 °C releases 2900 cal. The remaining 2400 cal melts 2400/80 = 30 g of ice, leaving 20 g of ice and 130 g of water at 0 °C.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-thermodynamics-kinetic-theory-62", "question": "In a sample of an ideal gas, the mass of each molecule is halved and the rms speed is doubled, the number of molecules per unit volume being unchanged. Then:", "options": ["the pressure doubles but the temperature is unchanged", "the pressure and the absolute temperature both double", "the pressure is unchanged but the temperature doubles", "the pressure and temperature both become four times"], "answer": 1, "explanation": "P = (1/3)nmv²_rms changes by (1/2) × 4 = 2. Temperature is set by the mean kinetic energy ½mv²_rms, which also changes by (1/2) × 4 = 2, so T doubles too.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-63", "question": "Two Carnot engines A and B work in series: A takes heat from a source at 800 K and rejects it at an intermediate temperature T; B takes this heat at T and rejects heat to a sink at 400 K. If the two engines do equal work, T is:", "options": ["565.7 K", "600 K", "500 K", "640 K"], "answer": 1, "explanation": "W_A = Q(800 − T)/800 and W_B = Q(T/800)(T − 400)/T = Q(T − 400)/800. Equal work gives 800 − T = T − 400, so T = 600 K. 565.7 K = √(800 × 400) is the condition for equal efficiencies.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-64", "question": "Two solid spheres of the same material and surface finish, of radii r and 2r, are at the same temperature in the same surroundings. The ratio of their initial rates of fall of temperature (smaller : larger) is:", "options": ["1 : 4", "1 : 2", "4 : 1", "2 : 1"], "answer": 3, "explanation": "Rate of heat loss ∝ area ∝ r², while heat capacity ∝ mass ∝ r³, so dT/dt ∝ 1/r: the smaller sphere cools twice as fast. 1 : 4 compares the heat lost, not the rate of fall of temperature.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-65", "question": "A gas taken from state A to state B along path 1 absorbs 80 J of heat and does 30 J of work. Along path 2 from A to B it absorbs 60 J. It is then returned from B to A along a third path in which 20 J of work is done on the gas. The work done by the gas along path 2, and the heat exchanged on the return path, are:", "options": ["10 J; 70 J released", "10 J; 30 J released", "30 J; 70 J absorbed", "10 J; 50 J released"], "answer": 0, "explanation": "ΔU_AB = 80 − 30 = 50 J, whatever the path. Path 2: W = 60 − 50 = 10 J. Return: ΔU = −50 J and W_by = −20 J, so Q = −50 − 20 = −70 J, i.e. 70 J released.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-66", "question": "Assertion (A): When two bodies at different temperatures are placed in thermal contact, their final common temperature need not be the mean of their initial temperatures.\nReason (R): The two bodies may have different heat capacities.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: heat lost equals heat gained, C₁(T₁ − T) = C₂(T − T₂), so T is the heat-capacity-weighted mean, which equals the simple mean only when C₁ = C₂.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-67", "question": "Match the gas (List I) with its ratio γ = C_p/C_v (List II).\nList I: (P) monatomic gas; (Q) rigid diatomic gas; (R) diatomic gas with its vibrational mode also active; (S) rigid non-linear polyatomic gas.\nList II: (1) 4/3; (2) 9/7; (3) 7/5; (4) 5/3.", "options": ["P-4, Q-2, R-3, S-1", "P-3, Q-4, R-2, S-1", "P-4, Q-3, R-2, S-1", "P-4, Q-3, R-1, S-2"], "answer": 2, "explanation": "γ = 1 + 2/f with f = 3, 5, 7 (3 translational + 2 rotational + 2 vibrational) and 6 (3 + 3): 5/3, 7/5, 9/7 and 4/3. So P-4, Q-3, R-2, S-1.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-thermodynamics-kinetic-theory-68", "question": "The absolute temperature and the pressure of a gas are both doubled and its molecules are replaced by molecules of half the diameter. The mean free path becomes:", "options": ["2 times", "8 times", "unchanged", "4 times"], "answer": 3, "explanation": "λ = kT/(√2 π d² P). Doubling T and P cancel, and halving d multiplies λ by 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-69", "question": "An air bubble rises from the bottom of a lake 20 m deep, where the temperature is 27 °C, to the surface, where the temperature is 37 °C. Taking atmospheric pressure as equal to 10 m of water, the ratio of its volume at the surface to that at the bottom is:", "options": ["3", "3.1", "2.1", "2"], "answer": 1, "explanation": "Pressure at the bottom = 10 + 20 = 30 m of water = 3 atm. PV/T = constant gives V_top/V_bottom = (3/1) × (310/300) = 3.1. 3 ignores the temperature change; 2 forgets the atmospheric pressure.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-thermodynamics-kinetic-theory-70", "question": "For a diatomic gas (rigid molecules), the difference between the principal specific heats per gram is c_p − c_v = 0.0625 cal g⁻¹ K⁻¹. Taking R = 2 cal mol⁻¹ K⁻¹, the specific heat of the gas at constant volume is about:", "options": ["0.219 cal g⁻¹ K⁻¹", "0.094 cal g⁻¹ K⁻¹", "0.156 cal g⁻¹ K⁻¹", "2.5 cal g⁻¹ K⁻¹"], "answer": 2, "explanation": "Per gram, c_p − c_v = R/M, so M = 2/0.0625 = 32 g/mol (oxygen). Then c_v = (5/2)R/M = 5/32 ≈ 0.156 cal g⁻¹ K⁻¹; 0.219 is c_p, and 2.5 is the molar value in units of R.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-71","question":"Heat is supplied at constant pressure to a rigid diatomic ideal gas. What fraction of the heat supplied goes into raising its internal energy?","options":["5/7","2/7","3/5","2/5"],"answer":0,"explanation":"ΔU/Q = nC_vΔT/(nC_pΔT) = C_v/C_p = (5R/2)/(7R/2) = 5/7; the remaining 2/7 (= R/C_p) is the work done. Picking 2/7 means you found the work fraction instead.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-72","question":"1 kg of ice at 0 °C melts completely into water at 0 °C (latent heat of fusion 3.36 × 10⁵ J/kg). The change in entropy of the ice–water is about:","options":["zero, since the temperature does not change","+1.23 × 10³ J/K","−1.23 × 10³ J/K","+3.36 × 10⁵ J/K"],"answer":1,"explanation":"Melting is a reversible heat intake at constant T, so ΔS = Q/T = 3.36 × 10⁵ / 273 ≈ 1.23 × 10³ J/K, and it is positive because heat is absorbed. Constant temperature does not mean zero entropy change.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-73","question":"An ideal gas is compressed from volume V to V/2, once isothermally and once adiabatically, starting from the same state. Which statement is correct?","options":["More work is needed in the isothermal compression because the gas must lose heat","Equal work is needed since the volume change is the same","More work is needed in the adiabatic compression because the pressure rises faster","The adiabatic compression needs no work because Q = 0"],"answer":2,"explanation":"On a P–V diagram the adiabat through the starting point is steeper (slope γ times the isotherm's), so during compression it lies above the isotherm and encloses more area: the adiabatic compression needs more work. The work then appears as a rise in internal energy.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-74","question":"At a high temperature all vibrational modes of CO₂ (a linear triatomic molecule) are fully excited. Treating it as an ideal gas obeying equipartition, its ratio γ = C_p/C_v is:","options":["4/3","11/9","7/5","15/13"],"answer":3,"explanation":"A linear molecule of N = 3 atoms has 3 translational, 2 rotational and 3N − 5 = 4 vibrational modes; each vibrational mode carries kinetic plus potential energy, i.e. R per mole. C_v = (3/2 + 1 + 4)R = 13R/2, C_p = 15R/2, γ = 15/13. Counting each vibration as only R/2 gives the trap 11/9.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-75","question":"An engine runs a monatomic ideal gas through a cycle of two reversible adiabats and two isochores (an Otto cycle) with compression ratio V_max/V_min = 8. Its efficiency is:","options":["3/4","7/8","1/2","2/3"],"answer":0,"explanation":"For the Otto cycle η = 1 − r^(1−γ) = 1 − 8^(−2/3) = 1 − 1/4 = 3/4, because along each adiabat T changes by the factor 8^(2/3) = 4. Using 1 − 1/r = 7/8 ignores γ.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-76","question":"A fixed mass of an ideal gas is kept in a rigid container and its absolute temperature is made four times as large. The number of collisions a given molecule makes per second with other molecules:","options":["stays the same","doubles","becomes four times","is halved"],"answer":1,"explanation":"In a rigid container the number density n is fixed, so the mean free path λ = 1/(√2 π d² n) does not change. Collision frequency = v_avg/λ, and v_avg ∝ √T doubles, so the frequency doubles. Saying 'unchanged' confuses λ with frequency.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-77","question":"Equal masses of helium and oxygen (rigid diatomic) are kept at the same temperature. The ratio of the total kinetic energy (all modes) of the helium to that of the oxygen is:","options":["8 : 1","8 : 5","24 : 5","5 : 24"],"answer":2,"explanation":"Moles are in the ratio (m/4) : (m/32) = 8 : 1, and the energy per mole is (3/2)RT for He and (5/2)RT for O₂. Ratio = 8 × 3 : 1 × 5 = 24 : 5. Counting only translational energy gives 8 : 1.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-78","question":"A liquid stands in a cylindrical glass vessel whose coefficient of linear expansion is α. On heating, the height of the liquid column, measured with a scale that does not itself expand, stays exactly the same. The coefficient of volume expansion of the liquid is:","options":["3α/2","α","3α","2α"],"answer":3,"explanation":"New height = V(1 + γΔT)/[A(1 + 2αΔT)], because the base area of the vessel grows by the factor (1 + 2αΔT). The height is unchanged when γ = 2α. 3α would keep the liquid at the same graduation mark on the expanding vessel, which is a different condition.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-79","question":"A beam of nitrogen molecules (mass 4.65 × 10⁻²⁶ kg each) moving at 500 m/s strikes a wall at 60° to the normal and rebounds elastically. If 5 × 10²¹ molecules hit an area of 1 cm² every second, the pressure on the wall is about:","options":["1.16 × 10³ Pa","581 Pa","2.01 × 10³ Pa","2.33 × 10³ Pa"],"answer":0,"explanation":"Only the normal component reverses: Δp per molecule = 2mv cos 60° = 2 × 4.65 × 10⁻²⁶ × 500 × 0.5 = 2.325 × 10⁻²³ kg m/s. Pressure = 5 × 10²¹ × 2.325 × 10⁻²³ / 10⁻⁴ ≈ 1.16 × 10³ Pa. Missing the factor 2 gives 581 Pa; using sin 60° gives 2.01 × 10³ Pa.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-80","question":"A thermally insulated box containing oxygen (rigid diatomic, molar mass 32 g/mol) moves at 100 m/s and is suddenly stopped. If all the ordered kinetic energy of the gas becomes internal energy, its temperature rises by about (R = 8.31 J/mol K):","options":["1.28 K","0.77 K","0.55 K","0.38 K"],"answer":1,"explanation":"Per mole: (1/2)Mv² = C_vΔT = (5/2)RΔT, so ΔT = Mv²/(5R) = 0.032 × 10⁴/(5 × 8.31) ≈ 0.77 K. Using (3/2)R (monatomic) gives 1.28 K, and using C_p = (7/2)R gives 0.55 K; the box is rigid, so C_v applies.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-81","question":"One mole of a monatomic ideal gas expands along the straight-line process P = P₀ − αV (P₀, α positive constants), starting at a small volume. The gas stops absorbing heat and starts rejecting it when its volume reaches:","options":["P₀/(2α)","P₀/α","5P₀/(8α)","3P₀/(4α)"],"answer":2,"explanation":"dQ = C_v dT + P dV with RT = PV: dQ = (3/2)(P dV + V dP) + P dV = [(5/2)(P₀ − αV) − (3/2)αV] dV = [(5/2)P₀ − 4αV] dV, which changes sign at V = 5P₀/(8α). P₀/(2α) is where the temperature is maximum; between the two the gas still absorbs heat though it cools, because it does more work than its loss of internal energy.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-82","question":"A solid rod of length L has a circular cross-section whose radius increases linearly from r at one end to 2r at the other; its curved surface is insulated. The narrow end is kept at 100 °C and the wide end at 0 °C. In the steady state the temperature at the middle of the rod is about:","options":["40 °C","66.7 °C","50 °C","33.3 °C"],"answer":3,"explanation":"Thermal resistance from the narrow end to x is (L/πKr²)[1 − 1/(1 + x/L)]: the whole rod gives L/(2πKr²) and the first half gives L/(3πKr²), i.e. 2/3 of the total. Two-thirds of the 100 °C drop occurs in the narrow half, so T_mid = 100 − 66.7 ≈ 33.3 °C. 50 °C assumes a uniform rod; 66.7 °C puts the drop in the wrong half.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-83","question":"A reversible engine working between 600 K and 300 K drives a reversible refrigerator that extracts heat from a cold box at 250 K and rejects it at 300 K. For every 1 J of heat the engine takes from the 600 K source, the heat removed from the cold box is:","options":["2.5 J","0.5 J","5 J","1.25 J"],"answer":0,"explanation":"Engine: η = 1 − 300/600 = 1/2, so W = 0.5 J. Refrigerator: COP = T_c/(T_h − T_c) = 250/50 = 5, so heat removed = 5 × 0.5 = 2.5 J. Answering 5 J forgets that only half the input heat becomes work.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-84","question":"One mole of a monatomic ideal gas at pressure P₀ and temperature T₀ is held in a thermally insulated cylinder by a light piston. The external pressure on the piston is suddenly raised to 2P₀ and kept there until the gas settles. The final temperature is:","options":["1.32 T₀","1.40 T₀","2.00 T₀","1.25 T₀"],"answer":1,"explanation":"The compression is adiabatic but irreversible, against a constant 2P₀: ΔU = −W gives (3/2)R(T − T₀) = −2P₀(V − V₀) with V = RT/2P₀ and V₀ = RT₀/P₀, so 1.5T − 1.5T₀ = −T + 2T₀ and T = 1.4T₀. The reversible formula T₀ × 2^(0.4) ≈ 1.32T₀ does not apply to a sudden compression.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-85","question":"Assertion (A): The molar heat capacity of an ideal gas is positive in every process, since heat must be supplied to raise its temperature.\nReason (R): For a polytropic expansion PVⁿ = constant with 1 < n < γ, the molar heat capacity C = R/(γ − 1) − R/(n − 1) is negative.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true: with 1 < n < γ, R/(n − 1) > R/(γ − 1), so C < 0, and during such an expansion the gas absorbs heat (dQ > 0) while its temperature falls (dT < 0), because it does more work than the heat it takes in. That makes A false; C is also infinite for an isothermal process and zero for an adiabatic one.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-86","question":"For one mole of a monatomic ideal gas, match the process (List I) with its molar heat capacity (List II).\nList I: (P) isobaric; (Q) isochoric; (R) P ∝ V; (S) PV³ = constant.\nList II: (1) R; (2) 3R/2; (3) 2R; (4) 5R/2.","options":["P-3, Q-2, R-4, S-1","P-4, Q-2, R-1, S-3","P-4, Q-2, R-3, S-1","P-2, Q-4, R-3, S-1"],"answer":2,"explanation":"For PVⁿ = constant, C = C_v + R/(1 − n) with C_v = 3R/2. Isobaric (n = 0): 5R/2; isochoric: 3R/2; P ∝ V (n = −1): 3R/2 + R/2 = 2R; PV³ (n = 3): 3R/2 − R/2 = R.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-87","question":"Two identical metal blocks, each of heat capacity 800 J/K, are at 80 °C and 20 °C. They are joined by a rod of thermal conductance KA/L = 2 W/K; the rod's heat capacity is negligible and there are no other losses. The time after which the temperature difference between the blocks becomes 30 °C is about:","options":["139 s","69 s","200 s","277 s"],"answer":0,"explanation":"d(ΔT)/dt = −(G/C₁ + G/C₂)ΔT = −(2G/C)ΔT, so ΔT decays with time constant C/2G = 800/4 = 200 s. Halving takes 200 ln 2 ≈ 139 s. Using C/G (forgetting that both blocks change temperature) gives 277 s; dropping ln 2 gives 200 s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-88","question":"A small blackened sphere is heated electrically inside an evacuated enclosure whose walls are at 300 K, and it reaches a steady temperature of 600 K. If the electrical power is doubled, its new steady temperature is about:","options":["714 K","1200 K","849 K","708 K"],"answer":3,"explanation":"In steady state P ∝ T⁴ − T₀⁴. So T⁴ = 2(600⁴ − 300⁴) + 300⁴ = 2.511 × 10¹¹ K⁴, giving T ≈ 708 K. Ignoring the absorption from the walls gives 600 × 2^(1/4) ≈ 714 K.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-89","question":"One mole of a monatomic ideal gas is taken round the cycle A(P₀, V₀) → B(2P₀, 2V₀) along a straight line on the P–V diagram, then B → C(P₀, 2V₀) at constant volume, then C → A at constant pressure. The efficiency of the cycle is:","options":["1/12","1/3","1/9","1/6"],"answer":0,"explanation":"Net work = triangle area = (1/2)(P₀)(V₀) = 0.5P₀V₀. Heat is absorbed only on A → B (P ∝ V, so T rises throughout): Q = ΔU + W = (3/2)(4 − 1)P₀V₀ + 1.5P₀V₀ = 6P₀V₀. η = 0.5/6 = 1/12. Taking only ΔU = 4.5P₀V₀ as the heat input gives 1/9.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-90","question":"How many of the following statements are correct?\n(A) The entropy of an isolated system never decreases.\n(B) The entropy of an ideal gas does not change in a reversible adiabatic process.\n(C) In the free expansion of an ideal gas into vacuum the entropy of the gas is unchanged, because no heat enters it.\n(D) Over one complete Carnot cycle, the total entropy change of the engine and its two reservoirs is zero.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and D are correct. C is wrong: free expansion is irreversible, and its entropy change is found along a reversible path between the same states, ΔS = nR ln(V₂/V₁) > 0, even though Q = 0 in the actual process.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-91","question":"How many of the following statements about ideal gases are correct?\n(A) At very low temperatures the molar heat capacity C_v of hydrogen approaches 3R/2, because its rotational modes freeze out.\n(B) In classical theory each fully excited vibrational mode adds R to the molar C_v.\n(C) C_p − C_v = R holds for an ideal gas even when its vibrational modes are active.\n(D) When the vibrational modes of a diatomic gas become active, its ratio γ = C_p/C_v increases.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and C are correct. D is wrong: γ = 1 + 2/f, and switching on vibrations increases f (from 5 to 7 for a diatomic gas), so γ falls from 7/5 to 9/7.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-92","question":"A vertical cylinder of cross-section 10 cm² contains air (γ = 1.4) in a column 35 cm high, closed by a frictionless piston of mass 1 kg; the equilibrium pressure of the air is 1.0 × 10⁵ Pa. The piston is pushed down slightly and released. Treating the compressions as adiabatic, the period of its small oscillations is about:","options":["0.37 s","0.31 s","0.44 s","0.22 s"],"answer":1,"explanation":"For displacement x, ΔP = γP₀(Ax)/(Ah) = γP₀x/h, so the restoring force is (γP₀A/h)x and ω² = γP₀A/(mh) = 1.4 × 10⁵ × 10⁻³/(1 × 0.35) = 400. T = 2π/20 ≈ 0.31 s. Treating the process as isothermal (no γ) gives about 0.37 s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-93","question":"A rigid, thermally insulated cylinder is divided by a frictionless, heat-conducting piston that can slide freely. One side holds 1 mol of helium at 300 K and the other 2 mol of nitrogen (rigid diatomic) at 600 K. The final common temperature is about:","options":["500 K","450 K","531 K","464 K"],"answer":2,"explanation":"The piston's work on one gas is taken from the other, and no heat leaves the cylinder, so the total internal energy is conserved: 1 × (3/2)R × 300 + 2 × (5/2)R × 600 = (1 × 3/2 + 2 × 5/2)R T, so T = 3450/6.5 ≈ 531 K. 500 K weights by moles only, ignoring the different C_v.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-94","question":"A long thick-walled pipe has inner radius r and outer radius 2r. In steady radial heat flow its inner surface is at 100 °C and its outer surface at 20 °C. The temperature in the wall is exactly 60 °C at a radius of:","options":["1.5r","1.25r","4r/3","√2 r"],"answer":3,"explanation":"For a cylindrical shell the thermal resistance from r to ρ is ln(ρ/r)/(2πKL), so T falls linearly with ln ρ. The mean temperature occurs where ln(ρ/r) = (1/2) ln 2, i.e. ρ = √2 r ≈ 1.41r, not at the arithmetic middle 1.5r. 4r/3 is the answer for a spherical shell.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-95","question":"How many of the following statements about thermal radiation are correct?\n(A) At a given temperature and wavelength, a good absorber of radiation is also a good emitter.\n(B) As the temperature of a black body rises, the wavelength of its most intense emission becomes shorter.\n(C) Doubling the absolute temperature of a black body doubles the power it radiates per unit area.\n(D) The rate of loss of heat by radiation from a hot body does not depend on the nature of its surface.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A (Kirchhoff's law) and B (Wien's law, λ_max T = constant) are correct. C is wrong: by Stefan's law the power per unit area grows 2⁴ = 16 times. D is wrong: the rate depends on the emissivity of the surface (polished surfaces radiate less than black ones).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-96","question":"A sealed container of an ideal gas is placed on a train moving smoothly at a constant 50 m/s. Compared with when the train was at rest (and the gas in equilibrium), the temperature of the gas is:","options":["higher by an amount proportional to 50²","higher, because the molecules move faster","lower","unchanged"],"answer":3,"explanation":"Temperature measures the random (thermal) kinetic energy of molecules relative to the centre of mass of the gas. Uniform bulk motion adds the same velocity to every molecule and does not change the random part, so T is unchanged.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-97","question":"An ideal gas in a rigid, closed container is heated. For this process:","options":["the internal energy remains constant","the heat supplied is entirely converted into work","the work done by the gas is zero and all the heat supplied increases the internal energy","the work done by the gas equals the heat supplied minus Cp ΔT"],"answer":2,"explanation":"In an isochoric process ΔV = 0, so W = ∫P dV = 0. The first law then gives Q = ΔU = nC_vΔT.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-98","question":"The absolute temperature of an ideal gas is doubled while its pressure is halved. The mean free path of its molecules becomes:","options":["2 times as large","4 times as large","unchanged","half as large"],"answer":1,"explanation":"λ = kT/(√2πd²P) ∝ T/P, i.e. inversely proportional to the number density. Doubling T and halving P quadruples the volume per molecule, so λ becomes 4 times as large.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-99","question":"A monatomic ideal gas undergoes a process in which the product of its pressure and absolute temperature stays constant (PT = constant). Its molar heat capacity for this process is:","options":["7R/2","5R/2","3R/2","−R/2"],"answer":0,"explanation":"With P = c/T and PV = nRT, V = nRT²/c, so dV/dT = 2V/T and P dV = 2nR dT. Hence C = C_v + P(dV/dT)/n = 3R/2 + 2R = 7R/2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-100","question":"One mole of a monatomic ideal gas is taken round a cycle: from A(P₀, V₀) along a straight line (which passes through the origin of the P–V diagram) to B(2P₀, 2V₀), then at constant volume to C(P₀, 2V₀), then at constant pressure back to A. The efficiency of this engine is:","options":["1/12 ≈ 8.3%","1/6 ≈ 16.7%","1/4 = 25%","1/9 ≈ 11.1%"],"answer":0,"explanation":"Net work = triangle area = ½P₀V₀. Heat enters only on A→B (T rises along a line with C = 2R > 0): ΔU = 1.5(4 − 1)P₀V₀ = 4.5P₀V₀ and W_AB = 1.5P₀V₀, so Q_in = 6P₀V₀. The other two legs reject heat. Efficiency = 0.5/6 = 1/12.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-101","question":"A freezer compartment is kept at 260 K in a room at 300 K. The minimum electrical energy needed to turn 1 kg of water already at 0 °C into ice (latent heat 3.36 × 10⁵ J/kg), assuming the heat is extracted at 260 K by an ideal refrigerator, is about:","options":["388 kJ","336 kJ","45 kJ","52 kJ"],"answer":3,"explanation":"An ideal (Carnot) refrigerator has COP = T_c/(T_h − T_c) = 260/40 = 6.5. The work needed is Q_c/COP = 3.36 × 10⁵/6.5 ≈ 5.2 × 10⁴ J. The heat dumped into the room is 3.36 × 10⁵ + 5.2 × 10⁴ ≈ 388 kJ.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-102","question":"A composite wall consists of slab P (thickness 2 cm, conductivity K) and slab Q (thickness 1 cm, conductivity 2K) in close contact. The outer face of P is at 100 °C and that of Q at 0 °C. In the steady state, the temperature of the interface is:","options":["80 °C","50 °C","20 °C","33.3 °C"],"answer":2,"explanation":"Thermal resistances (per unit area) are L/K: 2/K for P and 1/(2K) = 0.5/K for Q. The same heat current flows through both, so the 100 °C drop divides in the ratio 2 : 0.5. Q takes 100 × 0.5/2.5 = 20 °C, so the interface is at 20 °C.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-103","question":"On a cold day a pond starts freezing; the air temperature above it stays constant. A 1 cm thick layer of ice forms in the first hour. The time needed for the thickness to grow from 1 cm to 2 cm is:","options":["1 h","3 h","2 h","4 h"],"answer":1,"explanation":"Heat released by a new layer must be conducted through the ice already formed: ρL dx/dt = KΔT/x, so x dx ∝ dt and t ∝ x². Going from 0 to 1 cm takes 1 h (∝ 1²), so going from 1 cm to 2 cm takes ∝ 2² − 1² = 3 h.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-104","question":"A solid (volume expansion coefficient 3 × 10⁻⁵ K⁻¹) floats in a liquid (volume expansion coefficient 5 × 10⁻⁴ K⁻¹). When both are heated through 100 K, the fraction of the solid's volume that is submerged:","options":["increases by about 5.3%","increases by about 4.7%","decreases by about 4.7%","remains unchanged"],"answer":1,"explanation":"The submerged fraction equals ρ_s/ρ_l. Each density falls as ρ/(1 + γΔT), so the ratio changes by a factor ≈ 1 + (γ_l − γ_s)ΔT = 1 + 0.047. The liquid becomes relatively less dense, so the solid sinks deeper by about 4.7%.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-105","question":"A steel rod and a brass rod, of equal length and equal cross-section, are joined end to end and fitted snugly between two rigid walls at room temperature. Steel: α = 1.2 × 10⁻⁵ K⁻¹, Y = 2 × 10¹¹ Pa; brass: α = 1.8 × 10⁻⁵ K⁻¹, Y = 1 × 10¹¹ Pa. When the assembly is heated by 50 K, the compressive stress in the rods is:","options":["1 × 10⁸ Pa","1.2 × 10⁸ Pa","0.9 × 10⁸ Pa","1.5 × 10⁸ Pa"],"answer":0,"explanation":"The same force acts in both rods, and the total length cannot change: (α₁ + α₂)LΔT = σL(1/Y₁ + 1/Y₂). So σ = 3 × 10⁻⁵ × 50/(0.5 × 10⁻¹¹ + 1 × 10⁻¹¹) = 1.5 × 10⁻³/1.5 × 10⁻¹¹ = 1 × 10⁸ Pa.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-106","question":"A lead bullet at 27 °C strikes a steel plate and stops. Assuming all of its kinetic energy becomes heat in the bullet, the minimum speed for it to melt completely is about (lead: specific heat 128 J/kg K, melting point 327 °C, latent heat of fusion 2.5 × 10⁴ J/kg):","options":["503 m/s","277 m/s","252 m/s","356 m/s"],"answer":3,"explanation":"Per kilogram: heating 300 K needs 128 × 300 = 38400 J, and melting needs 25000 J, total 63400 J. So ½v² = 63400, v = √126800 ≈ 356 m/s. Forgetting the latent heat gives 277 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-107","question":"Two identical glass bulbs joined by a thin tube contain air at 27 °C and pressure P₀. One bulb is then kept at 27 °C while the other is heated to 127 °C (ignore expansion of the glass). The new pressure of the air is:","options":["7P₀/6","4P₀/3","8P₀/7","P₀"],"answer":2,"explanation":"The total number of moles is fixed and the pressure is common: P(V/300 + V/400) = 2P₀V/300. So P × 7/1200 = 8P₀/1200, giving P = 8P₀/7.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-108","question":"In a diesel engine, air (γ = 1.4) at 300 K is compressed quickly (adiabatically) to 1/32 of its volume. Its temperature becomes:","options":["600 K","9600 K","1200 K","2400 K"],"answer":2,"explanation":"TV^(γ−1) = constant, so T₂ = 300 × 32^0.4. Since 32^0.4 = 2^(5 × 0.4) = 2² = 4, T₂ = 1200 K, hot enough to ignite the injected fuel.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-109","question":"One mole of an ideal gas expands freely into a vacuum inside an insulated rigid container, doubling its volume. The change in its entropy is about (R = 8.31 J/mol K):","options":["zero, since no heat is exchanged","+5.76 J/K","−5.76 J/K","+8.31 J/K"],"answer":1,"explanation":"Entropy is a state function, so compute it along a reversible isothermal path between the same end states (T is unchanged in free expansion): ΔS = nR ln(V₂/V₁) = 8.31 × 0.693 ≈ 5.76 J/K. Q = 0 here, but the process is irreversible, so ΔS ≠ Q/T.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-110","question":"A fixed mass of an ideal gas is taken along a process whose volume–temperature (V–T) graph is a straight line that, when extended backwards, meets the V-axis at a POSITIVE value of V. As the temperature rises along this process, the pressure of the gas:","options":["increases","decreases","remains constant","first increases, then decreases"],"answer":0,"explanation":"Write V = V₀ + kT with V₀ > 0. Then P = nRT/V = nRT/(V₀ + kT) = nR/(V₀/T + k), which increases with T (approaching nR/k). Only a line through the origin would mean constant pressure.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-111","question":"For a monatomic ideal gas undergoing a process in which its internal energy is directly proportional to its volume, the ratio (heat absorbed)/(work done by the gas) is:","options":["1","3/2","5/3","5/2"],"answer":3,"explanation":"For an ideal gas U ∝ T, so U ∝ V means T ∝ V, i.e. the process is isobaric. Then Q = nC_pΔT = (5/2)nRΔT and W = PΔV = nRΔT, so Q/W = 5/2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-112","question":"For air (γ = 1.4) at a given temperature, the ratio of the speed of sound to the rms speed of the molecules is about:","options":["1.18","1.47","0.82","0.68"],"answer":3,"explanation":"v_sound = √(γRT/M) and v_rms = √(3RT/M), so their ratio is √(γ/3) = √(1.4/3) ≈ 0.68. Sound is slower than the rms molecular speed.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-113","question":"Estimate the mean free path of nitrogen molecules (effective diameter 3 × 10⁻¹⁰ m) at 300 K and 10⁵ Pa (k = 1.38 × 10⁻²³ J/K):","options":["3 × 10⁻¹⁰ m","1 × 10⁻⁹ m","1 × 10⁻⁷ m","1 × 10⁻⁵ m"],"answer":2,"explanation":"λ = kT/(√2πd²P) = (4.14 × 10⁻²¹)/(1.414 × 3.14 × 9 × 10⁻²⁰ × 10⁵) ≈ 4.14 × 10⁻²¹/4.0 × 10⁻¹⁴ ≈ 1.0 × 10⁻⁷ m, a few hundred molecular diameters.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-114","question":"A monatomic ideal gas at pressure P₀ and volume V₀ is held in a cylinder by a piston attached to a spring, which is relaxed initially; the atmosphere outside is at P₀. Heat is supplied slowly until the volume is 2V₀ and the pressure 3P₀ (the pressure rises linearly with volume). The heat supplied is:","options":["7.5P₀V₀","9.5P₀V₀","6P₀V₀","11.5P₀V₀"],"answer":1,"explanation":"Work = area under the straight P–V line = ½(P₀ + 3P₀)V₀ = 2P₀V₀. ΔU = (3/2)(P₂V₂ − P₁V₁) = 1.5(6 − 1)P₀V₀ = 7.5P₀V₀. So Q = 9.5P₀V₀.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-115","question":"At a given point (P, V) on the P–V diagram of an ideal gas, the ratio of the magnitude of the slope of the adiabatic curve to that of the isothermal curve through that point is:","options":["γ","1/γ","γ − 1","1"],"answer":0,"explanation":"Isothermal: PV = const gives dP/dV = −P/V. Adiabatic: PV^γ = const gives dP/dV = −γP/V. The adiabatic is steeper by the factor γ.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-116","question":"A small blackened body in an evacuated enclosure whose walls are at 300 K loses heat by radiation. When the body is at 500 K its net rate of heat loss is P. When it is at 400 K, its net rate of heat loss is about:","options":["0.32P","0.41P","0.5P","0.8P"],"answer":0,"explanation":"Net radiative loss ∝ T⁴ − T₀⁴. Ratio = (400⁴ − 300⁴)/(500⁴ − 300⁴) = (2.56 − 0.81)/(6.25 − 0.81) × 10¹⁰/10¹⁰ = 1.75/5.44 ≈ 0.32. Newton's law of cooling (∝ ΔT) would wrongly give 0.5.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-117","question":"On a new temperature scale X, water freezes at 20 °X and boils at 220 °X (at 1 atm). A temperature of 50 °C on this scale is:","options":["145 °X","100 °X","70 °X","120 °X"],"answer":3,"explanation":"The scales are linear: (X − 20)/(220 − 20) = (C − 0)/100. For C = 50, X − 20 = 100, so X = 120 °X.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-118","question":"A hot-air balloon has a fixed volume of 500 m³ and is open at the bottom. The outside air is at 300 K with density 1.2 kg/m³. The total mass of envelope, basket and passengers is 150 kg. The inside air must be heated to at least:","options":["450 K","375 K","400 K","360 K"],"answer":2,"explanation":"Lift requires (ρ_out − ρ_in)V ≥ 150 kg, so ρ_in ≤ 1.2 − 0.3 = 0.9 kg/m³. At the same (atmospheric) pressure ρ ∝ 1/T, so T_in = 300 × 1.2/0.9 = 400 K.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-119","question":"One mole of helium at 300 K and one mole of nitrogen (rigid diatomic) at 500 K are allowed to mix in a thermally insulated, rigid container (no work, no heat exchange). The final common temperature is:","options":["400 K","425 K","450 K","375 K"],"answer":1,"explanation":"Total internal energy is conserved: (3/2)R(300) + (5/2)R(500) = [(3/2 + 5/2)R]T. So T = (450 + 1250)/4 = 425 K, weighted towards nitrogen, which has more degrees of freedom.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-120","question":"A metal disc spins freely in space about its axis. Its temperature rises by 100 K (coefficient of linear expansion 1 × 10⁻⁵ K⁻¹), with no external torque. Its angular speed:","options":["decreases by about 0.1%","decreases by about 0.2%","increases by about 0.2%","remains unchanged"],"answer":1,"explanation":"Angular momentum Iω is conserved. I ∝ R² increases by 2αΔT = 2 × 10⁻³ = 0.2%, so ω decreases by about 0.2%.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-121","question":"A monatomic ideal gas is compressed adiabatically to one-eighth of its original volume. Its pressure becomes:","options":["32 times the original","8 times the original","4 times the original","128 times the original"],"answer":0,"explanation":"PV^γ = constant with γ = 5/3: P₂/P₁ = 8^(5/3) = 2⁵ = 32. (The temperature rises by 8^(2/3) = 4.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-122","question":"An ideal gas has γ = Cp/Cv = 9/7. The number of degrees of freedom of its molecules (all active) is:","options":["3.5","9","5","7"],"answer":3,"explanation":"γ = 1 + 2/f, so f = 2/(γ − 1) = 2/(2/7) = 7.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-123","question":"An ideal (Carnot) heat pump keeps a house at 300 K when the outside temperature is 270 K. For each 1 kW of electrical power it consumes, the rate at which it delivers heat to the house is:","options":["11 kW","9 kW","10 kW","1.11 kW"],"answer":2,"explanation":"For a heat pump, COP = Q_h/W = T_h/(T_h − T_c) = 300/30 = 10. So 1 kW of work delivers 10 kW of heat (9 kW of it drawn from outside).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-thermodynamics-kinetic-theory-124","question":"An ideal diatomic gas (γ = 1.4) at pressure P₀ is compressed rapidly (adiabatically) to 1/32 of its volume, and then held at this volume until it cools back to its original temperature. Its final pressure is:","options":["4P₀","128P₀","32P₀","P₀"],"answer":2,"explanation":"Adiabatic step: P = P₀ × 32^1.4 = 128P₀ and T rises 4-fold. Cooling at constant volume to the original T reduces P by that factor of 4, to 32P₀. The end state is the same as for an isothermal compression: PV = const between the end points.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-125","question":"Three identical metal rods are joined together at one common point. Their free ends are held at 100 °C, 70 °C and 10 °C, and the rods are insulated along their lengths. In the steady state, the temperature of the junction is:","options":["55 °C","60 °C","70 °C","40 °C"],"answer":1,"explanation":"The net heat current into the junction is zero: (100 − T) + (70 − T) + (10 − T) = 0 for identical rods, so T = 180/3 = 60 °C.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-thermodynamics-kinetic-theory-126","question":"A monatomic ideal gas is compressed adiabatically to half its volume. The rms speed of its molecules becomes about:","options":["1.26 times the original","1.59 times the original","1.41 times the original","2 times the original"],"answer":0,"explanation":"TV^(γ−1) = constant with γ − 1 = 2/3, so T increases by 2^(2/3). Since v_rms ∝ √T, it increases by 2^(1/3) ≈ 1.26.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-127","question":"Uranium is enriched by letting UF₆ gas effuse through porous barriers. The molar masses of ²³⁵UF₆ and ²³⁸UF₆ are 349 g/mol and 352 g/mol. In a single effusion stage, the ratio of the effusion rates of the lighter to the heavier molecules is about:","options":["1.0000","1.0086","1.0128","1.0043"],"answer":3,"explanation":"By Graham's law, effusion rate ∝ v_avg ∝ 1/√M. Ratio = √(352/349) = √1.0086 ≈ 1.0043, which is why thousands of stages are needed.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-128","question":"At what temperature does the reading on the Kelvin scale equal the reading on the Fahrenheit scale?","options":["313.1","−40","459.7","574.6"],"answer":3,"explanation":"F = (9/5)(K − 273.15) + 32. Setting F = K: K − 1.8K = 32 − 491.67, so 0.8K = 459.67 and K ≈ 574.6. (−40 is where Celsius and Fahrenheit agree.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-thermodynamics-kinetic-theory-129","question":"A steel tyre of inner radius 0.5 m must be fitted onto a wheel whose radius is 0.3 mm larger. By how much at least must the tyre be heated so that it just slips on (α = 1.2 × 10⁻⁵ K⁻¹)?","options":["100 K","25 K","50 K","36 K"],"answer":2,"explanation":"All linear dimensions, including the hole's radius, expand: Δr = rαΔT. ΔT = 3 × 10⁻⁴/(0.5 × 1.2 × 10⁻⁵) = 50 K. When it cools, the tyre grips the wheel tightly.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
